mapper.update:
UPDATE events
SET status = #{status},
    updated_at = #{updatedAt}
WHERE id = #{id, typeHandler=com.hookflow.hookflow.common.mybatis.UuidTypeHandler}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM events
    WHERE tenant_id = #{tenantId, typeHandler=com.hookflow.hookflow.common.mybatis.UuidTypeHandler}
      AND idempotency_key = #{idempotencyKey}
)
